module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);
// Extension of input signals
wire [7:0] mul_a_ext = {4'b0, mul_a};
wire [7:0] mul_b_ext = {4'b0, mul_b};
// Generate partial products
wire [7:0] partial_product[3:0];
generate
    genvar i;
    for(i = 0; i < 4; i = i + 1) begin : gen_partial_products
        assign partial_product[i] = (mul_b_ext[i]) ? (mul_a_ext << i) : 'd0;
    end
endgenerate
// Registers for storing intermediate sums
reg [7:0] sum_tmp1, sum_tmp2;
// Sequential logic for stage 1
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        sum_tmp1 <= 8'd0;
        sum_tmp2 <= 8'd0;
    end else begin
        sum_tmp1 <= (mul_b_ext[0] ? mul_a_ext : 8'd0) + (mul_b_ext[1] ? mul_a_ext << 1 : 8'd0);
        sum_tmp2 <= (mul_b_ext[2] ? mul_a_ext << 2 : 8'd0) + (mul_b_ext[3] ? mul_a_ext << 3 : 8'd0);
    end
end
// Register for storing final product
reg [7:0] mul_out_reg;
// Sequential logic for stage 2
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        mul_out_reg <= 8'd0;
    end else begin
        mul_out_reg <= sum_tmp1 + sum_tmp2;
    end
end
// Assign final product to output
assign mul_out = mul_out_reg;
endmodule
